/* WordPress Core Layout CSS - Block Specific Only */
.is-layout-grid { display: grid; }
.is-layout-grid { grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr)); gap: 1.25rem; }
.is-layout-flex { display: flex; }
.is-layout-flex { flex-wrap: wrap; align-items: center; }
.wp-container-spectra-container-is-layout-1 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
.wp-container-spectra-container-is-layout-2 {
