/* spectra-blocks Static CSS */

/* Block: container */
.spectra-layout-guide.components-modal__frame.components-guide{max-height:800px}.spectra-layout-guide .components-guide__container{gap:10px}.spectra-layout-guide .components-button:hover svg{fill:var(--wp-components-color-accent,var(--wp-admin-theme-color,#2563eb))!important}.spectra-layout-guide .components-guide__page-image{align-items:center;background:#f8f9fa;border-radius:8px;display:flex;justify-content:center;margin-bottom:1rem}.spectra-layout-guide__page{margin:0 auto;max-width:520px;padding:1rem 2rem}.spectra-layout-guide__page h2{color:#1e1e1e;font-size:1.5rem;font-weight:600;line-height:1.2;margin:1rem 0}.spectra-layout-guide__page p{color:#757575;font-size:1rem;font-style:normal;font-weight:400;line-height:1.6;margin:1rem 0}.spectra-layout-guide__page strong{color:#1e1e1e;font-weight:600}.spectra-layout-guide__icon{margin-bottom:1rem}.spectra-layout-guide__icon .dashicon,.spectra-layout-guide__icon svg{color:var(--wp-components-color-accent,var(--wp-admin-theme-color,#2563eb))}.spectra-layout-guide__features{background:#f0f6ff;border-left:4px solid var(--wp-components-color-accent,var(--wp-admin-theme-color,#2563eb));border-radius:6px;margin:1.5rem 0;padding:1rem;text-align:left}.spectra-layout-guide__features strong{color:#1e1e1e;display:block;font-weight:600;margin-bottom:.5rem}.spectra-layout-guide__features ul{margin:0;padding-left:1.25rem}.spectra-layout-guide__features ul li{color:#555;line-height:1.4;margin:.25rem 0}.spectra-layout-guide__tip{background:#fff8e1;border-left:4px solid #ffc107;border-radius:6px;margin:1.5rem 0;padding:1rem;text-align:left}.spectra-layout-guide__tip strong{color:#1e1e1e;display:block;font-size:1rem;font-weight:600;margin-bottom:.5rem}.spectra-layout-guide__tip p{color:#666;line-height:1.5;margin:0}@media(max-width:768px){.spectra-layout-guide__page{padding:1.5rem}.spectra-layout-guide__layout-demo{margin:1.5rem 0;padding:1rem}.spectra-layout-guide__layout-demo.flex-demo{flex-direction:column;gap:.5rem}.spectra-layout-